fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8> {
    // Calculate the end index for the slice
    let end = offset + count;
    // Take a contiguous slice and clone it into a new Vec<u8>
    buffer[offset..end].to_vec()
}

